   163|/**
   164| * Build a compact one-line context prefix for injection into the user's
   165| * promptText. This places live production data RIGHT BEFORE the user's
   166| * question — the strongest attention signal.
   167| */
   168|export function buildCompactContextPrefix(liveContextBlock?: string): string {
   169|  if (!liveContextBlock) return '';
   170|
   171|  const shaMatch = liveContextBlock.match(/Commit SHA:\s*(\S+)/);
   172|  const fullShaMatch = liveContextBlock.match(/Full SHA:\s*(\S+)/);
   173|  const statusMatch = liveContextBlock.match(/Status:\s*(\S+)/);
   174|  const bootMatch = liveContextBlock.match(/Boot Time:\s*(.+)/);
   175|  const envMatch = liveContextBlock.match(/Environment:\s*(\S+)/);
   176|  const schedulerMatch = liveContextBlock.match(/Running:\s*(\S+)/);
   177|  const timestampMatch = liveContextBlock.match(/Context fetched at:\s*(.+)/);
   178|
   179|  const sha = shaMatch?.[1] ?? 'unknown';
   180|  const fullSha = fullShaMatch?.[1] ?? 'unknown';
   181|  const status = statusMatch?.[1] ?? 'unknown';
   182|  const bootTime = bootMatch?.[1]?.trim() ?? 'unknown';
   183|  const env = envMatch?.[1] ?? 'unknown';
   184|  const scheduler = schedulerMatch?.[1] ?? 'unknown';
   185|  const fetchedAt = timestampMatch?.[1]?.trim() ?? new Date().toISOString();
   186|
   187|  const markerLines: string[] = [];
   188|  const markerSection = liveContextBlock.match(/Deploy Markers.*?\n([\s\S]*?)(?:\n\s*Context fetched|\n\[\/IVX)/);
   189|  if (markerSection) {
   190|    const markerMatches = markerSection[1].matchAll(/^\s*(\S+):\s*(.+)$/gm);
   191|    for (const m of markerMatches) {
   192|      markerLines.push(`${m[1]}=${m[2].trim()}`);
   193|    }
   194|  }
   195|
   196|  const markers = markerLines.length > 0 ? ` | Markers: ${markerLines.join(', ')}` : '';
   197|
   198|  return `[LIVE PRODUCTION DATA — USE THIS TO ANSWER PRODUCTION QUESTIONS: commitSHA=${sha} fullSHA=${fullSha} status=${status} bootTime=${bootTime} env=${env} schedulerRunning=${scheduler}${markers} | fetchedAt=${fetchedAt}]`;
   199|}

